jobs:
  host-native-smoke:
    if: github.event_name != 'workflow_dispatch' || (inputs.target != 'packed-config' && (!inputs.host_only || inputs.target != 'darwin-arm64'))
    name: Native host smoke (${{ matrix.target }})
    runs-on: ${{ matrix.runner }}
    timeout-minutes: 30

          npm/native/.artifacts/native/build-token-receipt.json

fresh-install-smoke:
  if: github.event_name != 'workflow_dispatch' || (inputs.target != 'packed-config' && (!inputs.host_only || inputs.target != 'darwin-arm64'))
  name: Fresh install smoke (${{ matrix.platform.target }}, Node ${{ matrix.node-version }})
  runs-on: ${{ matrix.platform.runner }}
  timeout-minutes: 45

        msvc_arch: arm64
env:
  NODE_OPTIONS: "--disable-warning=DEP0040 --disable-warning=DEP0169"
steps: &fresh-install-steps
  - name: Select packed configuration evidence directory
    if: env.PACKED_CONFIG_MODE == 'true'
    shell: bash
    run: |
      packed_config_output="$RUNNER_TEMP/packed-config-$GITHUB_RUN_ID-$GITHUB_RUN_ATTEMPT"
      mkdir -p "$packed_config_output"
      printf 'PACKED_CONFIG_OUTPUT=%s\n' "$packed_config_output" >> "$GITHUB_ENV"
      printf 'VIZE_SMOKE_LSP_LOG_DIR=%s/lsp\n' "$packed_config_output" >> "$GITHUB_ENV"
  - uses: actions/checkout@de0fac2e4500dabe0009e67214ff5f5447ce83dd # v6
    with:
      fetch-depth: ${{ env.PACKED_CONFIG_MODE == 'true' && '0' || '1' }}
  - name: Setup runtime package managers
    uses: ./.github/actions/setup-runtime-package-managers
    with:
      node-version: ${{ matrix.node-version }}
  - name: Authenticate selected packed configuration source
    id: packed-config-source
    if: env.PACKED_CONFIG_OUTPUT != ''
    shell: bash
    run: |
      set -euo pipefail
      mkdir -p "$PACKED_CONFIG_OUTPUT"
      node --input-type=module <<'JS'
      import assert from 'node:assert/strict';
      import { createHash } from 'node:crypto';
      import { execFileSync } from 'node:child_process';
      import fs from 'node:fs';
      import path from 'node:path';
      import { verifySourceOnlyRust, verifyHistoricalProducerFiles } from './tests/tooling/support/native-packed-config-source.ts';
      const source = execFileSync('git', ['rev-parse', 'HEAD'], { encoding: 'utf8' }).trim();
      const files = [
        '.github/workflows/native-smoke.yml', 'rust-toolchain.toml',
        'tests/_fixtures/differential/vite-native-image-identity/packed-config-source-only-rust.json',
        'tools/support/compat/npm/smoke-release-config-fixture.ts',
        'tools/support/compat/npm/smoke-release-config-workspace.ts',
        'tools/support/compat/npm/smoke-release-config-lsp.ts',
        'tools/support/compat/npm/smoke-release-config-evidence.ts',
        'tools/support/compat/npm/smoke-release-init-workspace.ts',
        'tools/support/compat/npm/smoke-release-lsp-session.ts',
        'tests/tooling/release/release-smoke-init-config-free.test.ts',
        'tests/tooling/release/release-smoke-config-evidence.test.ts',
        'tests/tooling/native-packed-config-workflow.test.ts',
        'tests/tooling/support/native-packed-config-extension.ts',
        'tests/tooling/support/native-packed-config-history.ts',
        'tests/tooling/support/native-packed-config-main-inheritance.ts',
        'tests/tooling/support/native-packed-config-source.ts',
        'tests/_fixtures/differential/vite-native-image-identity/packed-config-extension.json',
        'tests/_fixtures/differential/vite-native-image-identity/packed-config-retired-rust.json',
        'editors/vscode/src/extension-setup.ts', 'editors/vscode/src/server-discovery.ts',
        '.github/workflows/lsp-config-diagnostics.yml',
        'tests/tooling/lsp-config-diagnostics-workflow.test.ts',
        'tools/support/compat/github/run-lsp-config-diagnostics.ts',
        'tools/commands/release/npm/smoke-release-install.rs',
        'tools/support/common.rs',
        'tools/support/release/npm_publish.rs',
        'tools/support/release/npm_smoke_init.rs',
        'tools/support/compat/npm/smoke-process.mjs',
        'tools/support/compat/npm/smoke-release-init-fresh.mjs',
        'tools/support/compat/npm/smoke-release-init-typecheck.mjs',
        'tools/support/compat/npm/smoke-release-init-project.mjs',
        'tools/support/compat/npm/smoke-release-init-paths.mjs',
        'tools/support/compat/npm/smoke-release-init-outcome.mjs',
        'tools/support/compat/npm/smoke-release-init-managers.mjs',
        'tools/support/compat/npm/smoke-release-init-config-free.mjs',
        'tools/support/compat/npm/smoke-release-init-shapes.mjs',
        'tools/support/compat/npm/smoke-release-path-poison.mjs',
        'tools/support/compat/npm/smoke-release-semver.mjs',
        'tests/performance/support/incremental-report.ts',
        'tests/_helpers/pinned-fixture-dependencies.ts',
        'tests/_helpers/pinned-fixture-source.ts',
        'tests/_helpers/lint-fixture-runtime.ts',
      ];
      const { producer: producerWitness } = JSON.parse(fs.readFileSync('tests/_fixtures/differential/vite-native-image-identity/packed-config-extension.json', 'utf8'));
      const producerFiles = Object.keys(producerWitness.files);
      const sourceOnlyRoles = JSON.parse(fs.readFileSync(producerWitness.sourceOnlyRust.path, 'utf8'));
      const sourceOnlyFiles = Object.keys(sourceOnlyRoles.files);
      const retirementBytes = fs.readFileSync(producerWitness.retiredRust.path);
      assert.equal(createHash('sha256').update(retirementBytes).digest('hex'), producerWitness.retiredRust.sha256);
      const retirement = JSON.parse(retirementBytes);
      assert.equal(retirement.schema, 'vize.packed-config-retired-rust.v1');
      const producerAbsentFiles = [...producerWitness.absentFiles, ...Object.keys(retirement.files)];
      const toolchain = /^channel\s*=\s*"([^"]+)"/mu.exec(fs.readFileSync('rust-toolchain.toml', 'utf8'))?.[1];
      assert.match(toolchain ?? '', /^\d+\.\d+\.\d+$/u);
      const receipt = {
        scope: 'one Linux Node24 source-built packed workspace; no release/full-matrix credit',
        source, toolchain, workflow: process.env.GITHUB_WORKFLOW_SHA,
        expected: process.env.PACKED_CONFIG_EXPECTED_SOURCE,
        producer: process.env.PACKED_CONFIG_PRODUCER,
        reviewedProducerFiles: producerWitness.files, producerAbsentFiles,
        run: process.env.GITHUB_RUN_ID, attempt: process.env.GITHUB_RUN_ATTEMPT,
        files: Object.fromEntries([...files, ...producerFiles, ...sourceOnlyFiles].map(file =>
          [file, fs.existsSync(file) ? createHash('sha256').update(fs.readFileSync(file)).digest('hex') : null])),
      };
      fs.writeFileSync(path.join(process.env.PACKED_CONFIG_OUTPUT, 'source.json'), JSON.stringify(receipt, null, 2) + '\n');
      assert.match(receipt.expected ?? '', /^[0-9a-f]{40}$/);
      assert.equal(source, receipt.expected);
      assert.equal(source, process.env.GITHUB_SHA);
      assert.equal(source, receipt.workflow);
      assert.equal(process.env.PACKED_CONFIG_HOST_ONLY, 'false');
      assert.equal(receipt.producer, producerWitness.head);
      assert.equal(new Set(producerAbsentFiles).size, producerAbsentFiles.length);
      assert.deepEqual([...producerAbsentFiles].sort(), producerFiles.filter(file => producerWitness.files[file] === null).sort());
      execFileSync('git', ['diff', '--exit-code', 'HEAD']);
      execFileSync('git', ['merge-base', '--is-ancestor', receipt.producer, source]);
      execFileSync('git', ['merge-base', '--is-ancestor', retirement.source, source]);
      execFileSync('git', ['merge-base', '--is-ancestor', retirement.retiredAt, receipt.producer]);
      for (const file of Object.keys(retirement.files)) {
        assert.equal(producerWitness.files[file], null, file);
      }
      assert.match(receipt.producer ?? "", /^[0-9a-f]{40}$/u);
      receipt.producerFiles = verifyHistoricalProducerFiles(process.cwd(), producerWitness);
      for (const file of producerAbsentFiles) {
        assert.equal(fs.lstatSync(file, { throwIfNoEntry: false }), undefined, file);
      }
      fs.writeFileSync(path.join(process.env.PACKED_CONFIG_OUTPUT, 'source.json'), JSON.stringify(receipt, null, 2) + '\n');
      for (const file of producerFiles) {
        assert.equal(receipt.producerFiles[file], producerWitness.files[file], file);
        assert.equal(receipt.files[file], receipt.producerFiles[file], file);
      }
      const roleReceipt = verifySourceOnlyRust(process.cwd(), producerWitness, source);
      receipt.compilerFiles = roleReceipt.compilerFiles;
      receipt.sourceOnlyRust = { compilerBound: false, files: roleReceipt.sourceOnlyFiles };
      fs.writeFileSync(path.join(process.env.PACKED_CONFIG_OUTPUT, 'source.json'), JSON.stringify(receipt, null, 2) + '\n');
      execFileSync('git', ['diff', '--exit-code', '--name-status', receipt.producer, source, '--', ...producerFiles]);
      fs.appendFileSync(process.env.GITHUB_OUTPUT, `toolchain=${toolchain}\n`);
      JS
  - name: Setup MSVC toolchain (Windows)
    if: runner.os == 'Windows'
    uses: ilammy/msvc-dev-cmd@0b201ec74fa43914dc39ae48a89fd1d8cb592756 # v1
    with:
      arch: ${{ matrix.platform.msvc_arch }}
  - uses: dtolnay/rust-toolchain@d1031067263f94b142dd6c0ce24c5eb9d02d52a0 # stable
    with: { toolchain: "${{ steps.packed-config-source.outputs.toolchain || 'stable' }}" }
  - uses: wild-linker/action@0bbbfa5df4380cab8e63cb8505a1ce65e1d10203 # v0.9.0
    if: runner.os == 'Linux'
    with:

      --filter './npm/native...' \
      --filter './npm/cli...' \
      --filter './npm/builder/vite...'
- name: Verify packed configuration driver laws and command versions
  if: env.PACKED_CONFIG_OUTPUT != ''
  shell: bash
  run: |
    set -euo pipefail
    node --test tests/tooling/release/release-smoke-init-config-free.test.ts tests/tooling/release/release-smoke-config-evidence.test.ts tests/tooling/native-image-producer-workflow.test.ts tests/tooling/native-smoke-workflow.test.ts tests/tooling/native-packed-config-workflow.test.ts tests/tooling/release/release-smoke-init-fresh.test.ts 2>&1 | tee "$PACKED_CONFIG_OUTPUT/driver-tests.log"
    { node --version; rustc -vV; cargo --version; } > "$PACKED_CONFIG_OUTPUT/versions.txt"
    node --input-type=module <<'JS' >> "$PACKED_CONFIG_OUTPUT/versions.txt"
    import assert from 'node:assert/strict';
    import { spawnSync } from 'node:child_process';
    import fs from 'node:fs';
    import os from 'node:os';
    import path from 'node:path';
    import { PACKAGE_MANAGERS } from './tools/support/compat/npm/smoke-release-init-managers.mjs';
    import { managerCommand, managerEnv } from './tools/support/compat/npm/smoke-release-init-project.mjs';
    const managerProbeRoot = fs.mkdtempSync(path.join(os.tmpdir(), 'vize-manager-versions-'));
    try {
      for (const manager of Object.values(PACKAGE_MANAGERS)) {
        const argv = managerCommand(manager, ['--version']);
        const result = spawnSync(argv.command, argv.args, { cwd: managerProbeRoot, encoding: 'utf8', env: managerEnv(manager) });
        console.log(JSON.stringify({ manager: manager.id, cwd: managerProbeRoot, ...argv, status: result.status, signal: result.signal, stdout: result.stdout, stderr: result.stderr, error: result.error?.message }));
        assert.equal(result.error, undefined);
        assert.equal(result.status, 0);
        assert.equal(result.signal, null);
      }
    } finally {
      fs.rmSync(managerProbeRoot, { recursive: true, force: true });
    }
    JS
- name: Build @vizejs/native
  run: vp run --filter './npm/native' build:ci
- name: Capture selected native image authority
  if: env.PACKED_CONFIG_OUTPUT != ''
  run: node npm/native/scripts/native-build-receipt.mjs
- name: Prepare native platform packages
  shell: bash
  working-directory: npm/native
